// Scripts for the static template, loaded on every page.
// Generated by `npm run export` from the inline scripts in src/.

// WHAT THIS FILE DOES
// When someone visits a page that doesn't exist, the server shows 404.html.
// That page has a sentence like:
//   "The requested URL /this-page was not found on this server."
// "/this-page" is only a placeholder. The code below swaps it for the
// address the visitor actually typed, such as "/pioneers/ada-lovelace.html".
//
// Every page loads this file, but only 404.html has an element marked with
// data-missing-path, so on the other pages the code finds nothing and does
// nothing.

// Show the address the visitor actually tried

// 1. document.querySelectorAll(...) searches the page for every element that
//    matches a CSS selector and returns them as a list.
//    '[data-missing-path]' is an attribute selector. It matches any element
//    that has a data-missing-path attribute, like this one in 404.html:
//      <code data-missing-path>/this-page</code>
//
// 2. .forEach(...) runs the function inside it once for each element in
//    that list.
//
// 3. (el) => { ... } is an arrow function. Each time it runs, "el" holds the
//    element currently being handled.
document.querySelectorAll('[data-missing-path]').forEach((el) => {
	// location.pathname is the path in the browser's address bar: everything
	// after the domain name. For https://example.com/oops.html it is "/oops.html".
	//
	// Setting el.textContent replaces the text inside the element, so the
	// placeholder "/this-page" becomes the real address.
	// textContent always treats the value as plain text, never as HTML. That
	// keeps it safe even if someone puts strange characters in the URL.
	el.textContent = location.pathname;
});
